package com.harish.student_management.service;
import com.harish.student_management.dto.*; import com.harish.student_management.dto.BusTrackingDtos.*; import com.harish.student_management.entity.*; import com.harish.student_management.exception.ResourceNotFoundException; import com.harish.student_management.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor @Transactional public class BusTrackingServiceImpl implements BusTrackingService {private final BusTripRepository trips;private final BusLocationRepository locations;private final BusTripEventRepository events;private final BusRepository buses;private final BusRouteRepository routes;private final StudentRepository students;private final StudentBusAllocationRepository allocations;private final Optional<NotificationPublisher> notifier;private final BusEtaProvider eta;
 public TrackingResponse start(TripRequest r){Bus b=buses.findById(r.busId).orElseThrow(()->new ResourceNotFoundException("Bus not found"));BusRoute route=routes.findById(r.routeId).orElseThrow(()->new ResourceNotFoundException("Route not found"));if(route.getBus()==null||!route.getBus().getId().equals(b.getId()))throw new IllegalArgumentException("Route must be assigned to selected bus");if(route.getDriver()==null)throw new IllegalArgumentException("Route must have an assigned driver");if(trips.findFirstByBusIdAndStatusOrderByStartedAtDesc(b.getId(),"STARTED").isPresent())throw new IllegalStateException("Bus already has an active trip");BusTrip trip=trips.save(BusTrip.builder().bus(b).route(route).startedAt(LocalDateTime.now()).status("STARTED").build());events.save(BusTripEvent.builder().trip(trip).eventType("BUS_STARTED").occurredAt(trip.getStartedAt()).build());return map(trip,null);}
 public TrackingResponse location(Long id,Long driverId,LocationRequest r){BusTrip t=find(id);validateDriver(t,driverId);if(!"STARTED".equals(t.getStatus()))throw new IllegalStateException("Trip is not active");if(!Double.isFinite(r.latitude)||!Double.isFinite(r.longitude)||(r.speed!=null&&(!Double.isFinite(r.speed)||r.speed<0)))throw new IllegalArgumentException("Invalid location or speed");var etaResult=eta.estimateMinutes(t,r.latitude,r.longitude);Integer etaValue=etaResult.isPresent()?etaResult.getAsInt():null;BusLocation l=locations.save(BusLocation.builder().trip(t).latitude(r.latitude).longitude(r.longitude).speed(r.speed).etaMinutes(etaValue).recordedAt(LocalDateTime.now()).build());if(r.speed!=null&&r.speed==0)delayNotification(t);return map(t,l);}
 public TrackingResponse current(Long busId){BusTrip t=trips.findFirstByBusIdAndStatusOrderByStartedAtDesc(busId,"STARTED").orElseThrow(()->new ResourceNotFoundException("No active trip for bus"));BusLocation l=locations.findFirstByTripIdOrderByRecordedAtDesc(t.getId()).orElseThrow(()->new ResourceNotFoundException("No location available"));return map(t,l);}
 public TrackingResponse event(Long id,Long driverId,EventRequest r){BusTrip t=find(id);validateDriver(t,driverId);if(!"STARTED".equals(t.getStatus()))throw new IllegalStateException("Trip is not active");String type=r.eventType.trim().toUpperCase();Set<String> valid=Set.of("BUS_STARTED","CHILD_BOARDED","SCHOOL_REACHED","CHILD_DROPPED","DELAY");if(!valid.contains(type))throw new IllegalArgumentException("Unsupported bus event");Student s=r.studentId==null?null:students.findById(r.studentId).orElseThrow(()->new ResourceNotFoundException("Student not found"));List<BusTripEvent> prior=events.findByTripIdOrderByOccurredAtAsc(id);if("BUS_STARTED".equals(type)&&prior.stream().anyMatch(e->"BUS_STARTED".equals(e.getEventType())))throw new IllegalStateException("Bus started event already recorded");if(("CHILD_BOARDED".equals(type)||"CHILD_DROPPED".equals(type))&&s==null)throw new IllegalArgumentException("Student is required for child events");if(s!=null&&!allocationsForRoute(t,s))throw new SecurityException("Student is not allocated to this route");if("SCHOOL_REACHED".equals(type)&&prior.stream().noneMatch(e->"BUS_STARTED".equals(e.getEventType())))throw new IllegalStateException("Bus must start before school reached");if("CHILD_DROPPED".equals(type)&&prior.stream().noneMatch(e->"CHILD_BOARDED".equals(e.getEventType())&&e.getStudent()!=null&&e.getStudent().getId().equals(s.getId())))throw new IllegalStateException("Child must board before being dropped");events.save(BusTripEvent.builder().trip(t).student(s).eventType(type).details(r.details).occurredAt(LocalDateTime.now()).build());if("DELAY".equals(type))delayNotification(t);return map(t,null);}
 public List<TrackingResponse> events(Long id){return events.findByTripIdOrderByOccurredAtAsc(id).stream().map(e->map(e.getTrip(),null,e.getEventType())).toList();}
 private void delayNotification(BusTrip t){notifier.ifPresent(n->{com.harish.student_management.dto.NotificationRequestDto r=new com.harish.student_management.dto.NotificationRequestDto();r.setType(NotificationTypes.BUS_UPDATE);r.setTitle("Bus delay update");r.setMessage("Bus " + t.getBus().getRegistrationNumber()+" may be delayed");r.setRecipientRole("PARENTS");n.publish(r);});}
 private BusTrip find(Long id){return trips.findById(id).orElseThrow(()->new ResourceNotFoundException("Trip not found"));}private void validateDriver(BusTrip t,Long driverId){if(t.getRoute().getDriver()==null||driverId==null||!t.getRoute().getDriver().getId().equals(driverId))throw new SecurityException("Driver is not assigned to this route");}private boolean allocationsForRoute(BusTrip t,Student s){return allocations.findByStudentId(s.getId()).stream().anyMatch(a->"ACTIVE".equalsIgnoreCase(a.getStatus())&&a.getRoute().getId().equals(t.getRoute().getId())&&a.getBus().getId().equals(t.getBus().getId()));}private TrackingResponse map(BusTrip t,BusLocation l){return map(t,l,null);}private TrackingResponse map(BusTrip t,BusLocation l,String e){return TrackingResponse.builder().tripId(t.getId()).busId(t.getBus().getId()).routeId(t.getRoute().getId()).routeName(t.getRoute().getName()).status(t.getStatus()).eventType(e).latitude(l==null?null:l.getLatitude()).longitude(l==null?null:l.getLongitude()).speed(l==null?null:l.getSpeed()).etaMinutes(l==null?null:l.getEtaMinutes()).timestamp(l==null?null:l.getRecordedAt()).build();}}
